import { lazy, Suspense, useEffect, useMemo, useState } from "react";
import type { CountryDefinition } from "../domain/types.js";
import type { AttributeId, CareerGameState, CampaignActionType, EducationId, ProfessionId, RealismMode, SocialOriginId } from "../domain/career-types.js";
import type { EconomicPolicyId, EconomicPolicyRoute, Ideology } from "../domain/types.js";
import { countrySchema } from "../data/schemas.js";
import { createGameState } from "../engine/simulation.js";
import { advanceCareer, advanceChallengeDays, appointMinister, applyBetrayalMemory, backSuccessor, canStartNextCareerCampaign, canStartMinisterialAppointment, canStartPartyLeadershipElection, castVote, changePartyAffiliation, createCareerGame, declineReturnCall, defendGovernment, foundParty, issueExecutiveDecree, negotiateGovernmentSupport, negotiateWithLegislator, nominate, performCampaignAction, performPartyLeadershipAction, performMinistryAction, resolveGovernmentChallenge, resolveGovernmentInvestiture, resolveInboxOption, retireCareer, returnFromRetirement, startGovernmentInvestiture, startMinisterialAppointment, startNextCareerCampaign, startPartyLeadershipElection, submitGovernmentChallenge, submitGovernmentProject } from "../application/career-commands.js";
import { economicPolicyApprovalPercent, economicPolicyCanBeDecreed, enactEconomicPolicy, executiveAuthorityPercent } from "../application/economic-commands.js";
import { economicModelParameters } from "../domain/economic-model.js";
import { exportCareer, importCareer, loadCareer, saveCareer } from "../persistence/career-save.js";
import { pressHeadlineTemplates } from "../data/press-headlines.js";
import { hashSeed } from "../engine/rng.js";
import { advanceGeopolitics, worldActorDefinitions } from "../engine/world-simulation.js";
const WorldView = lazy(() => import("./WorldView.js").then((module) => ({ default: module.WorldView })));
const HelpView = lazy(() => import("./HelpView.js").then((module) => ({ default: module.HelpView })));

const actions: { id: CampaignActionType; title: string; hint: string }[] = [
  { id: "door-knocking", title: "Recorrer el distrito", hint: "Contacto directo con votantes" },
  { id: "rally", title: "Organizar un mitin", hint: "Visibilidad y movilización" },
  { id: "media-interview", title: "Dar una entrevista", hint: "Instala tus prioridades" },
  { id: "primary-outreach", title: "Hablar con el partido", hint: "Asegura apoyo interno" },
  { id: "fundraising", title: "Recaudar fondos", hint: "Amplía el presupuesto" },
  { id: "make-promise", title: "Hacer una promesa", hint: "Compromiso que se cobrará en el mandato" },
];
function campaignActionCopy(action: CampaignActionType, officeId: string, country: CountryDefinition) {
  const ministerial = officeId === country.ministerialAppointment.officeId;
  const leadership = officeId === country.partyLeadership.officeId;
  const copy: Partial<Record<CampaignActionType, { title: string; hint: string }>> = ministerial ? {
    "door-knocking": { title: "Demostrar resultados", hint: "Presenta tu trayectoria de gestión al equipo ejecutivo" },
    rally: { title: "Defender la cartera", hint: "Explica por qué tu plan merece respaldo" },
    "media-interview": { title: "Responder a la prensa", hint: "Aclara tu experiencia y prioridades" },
    "primary-outreach": { title: "Presentar agenda al ejecutivo", hint: "Busca apoyo directo para el nombramiento" },
    fundraising: { title: "Recaudar fondos", hint: "Amplía los recursos para futuras campañas" },
  } : leadership ? {
    "door-knocking": { title: "Visitar comités del partido", hint: "Escucha a las facciones y sus bases" },
    rally: { title: "Convocar a la militancia", hint: "Moviliza apoyo para la votación interna" },
    "media-interview": { title: "Explicar la plataforma", hint: "Define tu línea ante la prensa" },
    "primary-outreach": { title: "Negociar con las facciones", hint: "Construye respaldo en la bancada" },
    fundraising: { title: "Recaudar fondos", hint: "Amplía los recursos para futuras campañas" },
  } : {};
  return copy[action] ?? actions.find((entry) => entry.id === action)!;
}
const errorMessage = (error: unknown) => error instanceof Error ? error.message : "Ocurrió un error inesperado.";
const origins: { id: SocialOriginId; label: string }[] = [{id:"urban-working",label:"Origen trabajador urbano"},{id:"rural-working",label:"Origen trabajador rural"},{id:"professional-middle",label:"Clase media profesional"},{id:"business-family",label:"Familia empresarial"},{id:"political-family",label:"Familia política"},{id:"military-family",label:"Familia militar"}];
const professions: { id: ProfessionId; label: string }[] = [{id:"lawyer",label:"Abogado/a"},{id:"doctor",label:"Médico/a"},{id:"teacher",label:"Docente"},{id:"union-organizer",label:"Dirigente sindical"},{id:"business-owner",label:"Empresario/a"},{id:"journalist",label:"Periodista"},{id:"military-officer",label:"Militar"},{id:"activist",label:"Activista"},{id:"economist",label:"Economista"},{id:"athlete",label:"Deportista"},{id:"civil-servant",label:"Funcionario/a"},{id:"academic",label:"Académico/a"}];
const educations: { id: EducationId; label: string }[] = [{id:"none",label:"Sin estudios formales"},{id:"technical",label:"Formación técnica"},{id:"public-university",label:"Universidad pública"},{id:"private-university",label:"Universidad privada"},{id:"abroad",label:"Estudios en el extranjero"}];
const traitOptions = [{id:"natural-orator",label:"Orador nato"},{id:"technocrat",label:"Tecnócrata"},{id:"incorruptible",label:"Incorruptible"},{id:"cunning",label:"Maquiavélico"},{id:"loyal",label:"Leal"},{id:"resentful",label:"Rencoroso"},{id:"populist",label:"Populista"},{id:"survivor",label:"Superviviente"}];
const attributeLabels: Record<AttributeId,string> = {charisma:"Carisma",oratory:"Oratoria",cunning:"Astucia",management:"Gestión",integrity:"Integridad",network:"Red de contactos",health:"Salud"};
const policyLabels: Record<EconomicPolicyId,string> = {"public-investment":"Inversión pública",austerity:"Austeridad","income-tax":"Impuesto a la renta","corporate-tax":"Impuesto corporativo","consumption-tax":"Impuesto al consumo","extractive-royalty":"Regalía extractiva","health-spending":"Gasto en salud","education-spending":"Gasto en educación","infrastructure-spending":"Infraestructura",subsidies:"Subsidios",transfers:"Transferencias",tariffs:"Aranceles","trade-opening":"Apertura comercial","labor-regulation":"Regulación laboral","environmental-regulation":"Regulación ambiental",privatization:"Privatización",nationalization:"Nacionalización","credit-easing":"Crédito expansivo","credit-tightening":"Crédito restrictivo","capital-controls":"Controles de capital","currency-defense":"Defensa cambiaria","imf-program":"Programa de estabilización","debt-restructuring":"Reestructuración de deuda",default:"Suspensión de pagos"};
const indicatorLabels: Record<string,string> = {gdpPerCapitaUsd:"PIB por persona",gdpGrowthPercent:"Crecimiento anual",inflationPercent:"Inflación",unemploymentPercent:"Desempleo",informalityPercent:"Informalidad",publicDebtPercentGdp:"Deuda pública / PIB",fiscalDeficitPercentGdp:"Déficit fiscal / PIB",tradeBalancePercentGdp:"Balanza comercial / PIB",currentAccountPercentGdp:"Cuenta corriente / PIB",reservesMonthsImports:"Reservas (meses de importación)",exchangeRateIndex:"Índice cambiario",policyRatePercent:"Tasa de política",creditRatingIndex:"Calificación crediticia",countryRiskBasisPoints:"Riesgo país (pb)",inequalityIndex:"Desigualdad",povertyPercent:"Pobreza",realWageIndex:"Índice de salario real",domesticInvestmentPercentGdp:"Inversión interna / PIB",foreignInvestmentPercentGdp:"Inversión extranjera / PIB",productivityIndex:"Índice de productividad"};

export function App() {
  const [country, setCountry] = useState<CountryDefinition | null>(null);
  const [countryOptions, setCountryOptions] = useState<readonly { id: string; name: string }[]>([]);
  const [state, setState] = useState<CareerGameState | null>(null);
  const [busy, setBusy] = useState(true);
  const [message, setMessage] = useState("");
  const [name, setName] = useState("");
  const [age, setAge] = useState(30);
  const [officeId, setOfficeId] = useState("deputy");
  const [districtId, setDistrictId] = useState("");
  const [partyId, setPartyId] = useState("");
  const [partySwitchTarget, setPartySwitchTarget] = useState("");
  const [foundPartyName, setFoundPartyName] = useState("");
  const [seed, setSeed] = useState<string>(crypto.randomUUID());
  const [realism, setRealism] = useState<RealismMode>("realistic");
  const [ironman, setIronman] = useState(false);
  const [wizardStep, setWizardStep] = useState(1);
  const [originId, setOriginId] = useState<SocialOriginId>("professional-middle");
  const [professionId, setProfessionId] = useState<ProfessionId>("teacher");
  const [educationId, setEducationId] = useState<EducationId>("public-university");
  const [ideology, setIdeology] = useState<Ideology>({economy:50,social:50,nationalism:50,institutionalism:55,rigidity:35});
  const [traits, setTraits] = useState<string[]>(["natural-orator","technocrat"]);
  const [attributes, setAttributes] = useState<Record<AttributeId,number>>({charisma:10,oratory:10,cunning:10,management:10,integrity:10,network:10,health:10});
  const [tab, setTab] = useState<"career" | "inbox" | "country" | "people" | "press" | "economy" | "world" | "help">("career");
  const [economicPolicyId, setEconomicPolicyId] = useState<EconomicPolicyId>("public-investment");
  const [memberQuery, setMemberQuery] = useState("");
  const previewParties = useMemo(() => country ? createGameState(country, seed).parties : [], [country, seed]);

  useEffect(() => {
    const selectedId = new URLSearchParams(window.location.search).get("country") ?? "peru";
    Promise.all([fetch("/data/countries/index.json").then((response) => response.json()), loadCareer().catch((error) => { setMessage(`El guardado local no se pudo abrir: ${errorMessage(error)}. Puedes importar una copia o iniciar una nueva carrera.`); return null; })])
      .then(async ([manifest, saved]) => {
        const available = (manifest as { countries: { id: string; name: string; file: string }[] }).countries;
        setCountryOptions(available.map(({ id, name }) => ({ id, name })));
        const selected = available.find((entry) => entry.id === selectedId) ?? available[0];
        if (!selected) throw new Error("El catálogo no contiene países disponibles.");
        const raw = await fetch(`/data/countries/${selected.file}`).then((response) => response.json());
        const loaded = countrySchema.parse(raw) as CountryDefinition;
        setCountry(loaded); setDistrictId(loaded.electoralDistricts.find((district) => (district.seatsByChamber[loaded.politicalSystem.legislature.lowerChamber.id] ?? 0) > 0)?.id ?? ""); setPartyId(saved?.playerPartyId ?? ""); setOfficeId(saved?.campaign.officeId ?? (loaded.candidateEligibility.some((candidate) => candidate.officeId === "deputy") ? "deputy" : loaded.candidateEligibility[0]?.officeId ?? "deputy"));
        if (saved?.countryId === loaded.id) setState(saved);
      })
      .catch((error) => setMessage(`No se pudo cargar el escenario: ${errorMessage(error)}`))
      .finally(() => setBusy(false));
  }, []);

  useEffect(() => { if (state) void saveCareer(state).catch((error) => setMessage(`No se pudo guardar: ${errorMessage(error)}`)); }, [state]);

  const party = useMemo(() => state?.world.parties.find((candidate) => candidate.id === state.playerPartyId), [state]);
  const legislatorCount = state?.world.legislators.filter((person) => person.chamberId === state.legislature?.chamberId).length ?? 0;
  const latestBudgetVote = state?.budget.voteHistory.at(-1);
  const visibleMembers = state?.world.legislators.filter((member) => (!state.legislature || member.chamberId === state.legislature.chamberId) && `${member.name} ${member.id} ${state.world.parties.find((candidate)=>candidate.id===member.partyId)?.name ?? ""}`.toLocaleLowerCase().includes(memberQuery.toLocaleLowerCase())).slice(0, 30) ?? [];
  const pressItems = state ? [...state.inbox.map((item)=>({id:item.id,subject:item.title,source:item.category,explanation:item.explanation,turn:item.createdAtTurn})),...(state.legislature?.voteHistory.map((vote)=>({id:vote.proposal.id,subject:vote.proposal.title,source:"congreso",explanation:vote.explanation,turn:vote.turn}))??[])].slice(-40).reverse().map((item)=>({...item,headline:pressHeadlineTemplates[hashSeed(`${state.seed}:${item.id}`)%pressHeadlineTemplates.length]!.replace("{subject}",item.subject)})) : [];

  function run(operation: () => CareerGameState) {
    try { setState(operation()); setMessage(""); }
    catch (error) { setMessage(errorMessage(error)); }
  }

  function adjustAttribute(attribute: AttributeId, raw: number) {
    const target = Math.max(1, Math.min(20, raw));
    const difference = target - attributes[attribute];
    const others = (Object.keys(attributes) as AttributeId[]).filter((key) => key !== attribute);
    const next = { ...attributes, [attribute]: target };
    let remaining = Math.abs(difference);
    for (const key of others) {
      if (!remaining) break;
      const capacity = difference > 0 ? next[key] - 1 : 20 - next[key];
      const change = Math.min(remaining, capacity);
      next[key] += difference > 0 ? -change : change;
      remaining -= change;
    }
    if (remaining) setMessage("No quedan puntos disponibles en los demás atributos.");
    else { setAttributes(next); setMessage(""); }
  }

  if (busy) return <main className="loading">Preparando el escenario…</main>;
  if (!country) return <main className="loading">{message || "No hay un escenario disponible."}</main>;

  return <main className="app-shell">
    <aside className="rail"><div className="brand-mark">M</div><div className="rail-label">MANDATO<br/><span>CARRERA POLÍTICA</span></div><div className="rail-spacer"/>
      <button className={tab === "career" ? "rail-button active" : "rail-button"} onClick={() => setTab("career")}>01 <span>Carrera</span></button>
      <button className={tab === "inbox" ? "rail-button active" : "rail-button"} onClick={() => setTab("inbox")}>02 <span>Bandeja</span></button>
      <button className={tab === "people" ? "rail-button active" : "rail-button"} onClick={() => setTab("people")}>03 <span>Congreso</span></button>
      <button className={tab === "press" ? "rail-button active" : "rail-button"} onClick={() => setTab("press")}>04 <span>Prensa</span></button>
      <button className={tab === "economy" ? "rail-button active" : "rail-button"} onClick={() => setTab("economy")}>05 <span>Economía</span></button>
      <button className={tab === "world" ? "rail-button active" : "rail-button"} onClick={() => setTab("world")}>06 <span>Mundo</span></button>
      <button className={tab === "country" ? "rail-button active" : "rail-button"} onClick={() => setTab("country")}>07 <span>País</span></button>
      <button className={tab === "help" ? "rail-button active" : "rail-button"} onClick={() => setTab("help")}>08 <span>Ayuda</span></button>
      {state && <div className="rail-tools"><button onClick={() => exportCareer(state)}>Exportar partida</button>{state.ironman ? <span className="file-label">IRONMAN · guardado único</span> : <label className="file-label">Importar partida<input type="file" accept="application/json" onChange={(event) => { const file = event.target.files?.[0]; if (file) void importCareer(file).then(setState).catch((error) => setMessage(errorMessage(error))); }}/></label>}<button onClick={() => { if (state.ironman && !window.confirm("Nueva carrera reemplazará tu único guardado Ironman. ¿Continuar?")) return; setState(null); setSeed(crypto.randomUUID()); }}>Nueva carrera</button></div>}
    </aside>
    <section className="main-column"><header className="topbar"><div><span className="eyebrow">REPÚBLICA · ESCENARIO {country.startingYear}</span><h1>{state ? state.player.name : "Una carrera. Un país real."}</h1></div><div className="top-status"><span className="live-dot"/>{state ? stageLabel(state) : "NUEVA PARTIDA"}</div></header>
      {message && <div className="alert" role="alert">{message}<button onClick={() => setMessage("")}>×</button></div>}
      {!state && tab === "help" ? <Suspense fallback={<p role="status">Cargando ayuda…</p>}><HelpView/></Suspense> : !state ? <section className="welcome-grid"><div className="welcome-copy"><span className="eyebrow">LA POLÍTICA SE HACE EN PERSONA</span><h2>Tu nombre aún<br/>no está en la lista.</h2><p>Construye apoyo desde tu distrito, consigue una candidatura y gana un escaño. Los partidos y representantes se generan para esta partida; las instituciones corresponden al país.</p><label>País de inicio<select aria-label="País de inicio" value={country.id} onChange={(event)=>{const target=new URL(window.location.href);target.searchParams.set("country",event.target.value);window.location.assign(target.toString());}}>{countryOptions.map((option)=><option key={option.id} value={option.id}>{option.name}</option>)}</select></label><div className="country-inline"><strong>{country.name}</strong><span>{country.politicalSystem.formOfGovernment} · {country.politicalSystem.legislature.type === "bicameral" ? `${country.politicalSystem.legislature.lowerChamber.seats} + ${country.politicalSystem.legislature.upperChamber.seats} escaños` : `${country.politicalSystem.legislature.lowerChamber.seats} escaños`}</span></div></div>
        <form className="creation-card wizard-card" onSubmit={(event) => { event.preventDefault(); if (wizardStep < 6) { setWizardStep(wizardStep + 1); return; } try { const created = createCareerGame(country, { seed, name, age, originId, professionId, educationId, ideology, traitIds: traits, attributes, districtId, officeId, realism, ironman, ...(partyId ? { partyId } : {}) }); setState(created); } catch (error) { setMessage(errorMessage(error)); } }}>
          <span className="eyebrow">CREA TU PERSONAJE · PASO {wizardStep} DE 6</span><div className="wizard-progress" aria-label={`Paso ${wizardStep} de 6`}>{Array.from({length:6},(_,index)=><i key={index} className={index<wizardStep?"done":""}/>)}</div>
          {wizardStep===1&&<><h3>Tu origen</h3><label>Nombre público<input required minLength={2} maxLength={64} value={name} onChange={(event) => setName(event.target.value)} placeholder="¿Cómo te llamas?"/></label><label>Origen social<select value={originId} onChange={(event)=>setOriginId(event.target.value as SocialOriginId)}>{origins.map((item)=><option key={item.id} value={item.id}>{item.label}</option>)}</select></label><label>Cargo inicial<select value={officeId} onChange={(event)=>{const nextOffice=event.target.value;setOfficeId(nextOffice);const chamber=country.candidateEligibility.find((candidate)=>candidate.officeId===nextOffice)?.chamberId??country.politicalSystem.legislature.lowerChamber.id;setDistrictId(country.electoralDistricts.find((item)=>(item.seatsByChamber[chamber]??0)>0)?.id??"");}}>{country.candidateEligibility.map((candidate)=><option key={candidate.officeId} value={candidate.officeId}>{candidate.officeId}</option>)}</select></label>{officeId!==country.politicalSystem.executive.officeId&&<label>Circunscripción<select value={districtId} onChange={(event) => setDistrictId(event.target.value)}>{country.electoralDistricts.filter((district)=>(district.seatsByChamber[country.candidateEligibility.find((candidate)=>candidate.officeId===officeId)?.chamberId??country.politicalSystem.legislature.lowerChamber.id]??0)>0).map((district) => <option key={district.id} value={district.id}>{district.name}</option>)}</select></label>}<label>Semilla de la partida<input value={seed} onChange={(event)=>setSeed(event.target.value)} maxLength={64}/></label><label>Nivel de realismo<select value={realism} onChange={(event)=>setRealism(event.target.value as RealismMode)}><option value="relaxed">Relajado · avisos claros, memoria atenuada</option><option value="realistic">Realista · comportamiento estándar</option><option value="relentless">Implacable · rivales persistentes e información parcial</option></select></label><p className="wizard-help">El nivel modifica decisiones e información de los NPC; no entrega ni quita recursos.</p><label><input type="checkbox" checked={ironman} onChange={(event)=>setIronman(event.target.checked)}/> Ironman · un guardado automático, sin importar partidas anteriores</label></>}
          {wizardStep===2&&<><h3>Tu profesión</h3><p className="wizard-help">Tu trayectoria aporta contactos y habilidades iniciales.</p><label>Profesión previa<select value={professionId} onChange={(event)=>setProfessionId(event.target.value as ProfessionId)}>{professions.map((item)=><option key={item.id} value={item.id}>{item.label}</option>)}</select></label></>}
          {wizardStep===3&&<><h3>Tu formación</h3><p className="wizard-help">El prestigio y la gestión inicial dependen de tu experiencia educativa.</p><label>Formación<select value={educationId} onChange={(event)=>setEducationId(event.target.value as EducationId)}>{educations.map((item)=><option key={item.id} value={item.id}>{item.label}</option>)}</select></label></>}
          {wizardStep===4&&<><h3>Tu ideología</h3><p className="wizard-help">Define posiciones y rigidez. Los ejes influirán en la afinidad y los votos.</p>{(["economy","social","nationalism","institutionalism","rigidity"] as const).map((key)=> <label className="range-label" key={key}><span>{({economy:"Estado fuerte ↔ mercado",social:"Conservadurismo ↔ progresismo",nationalism:"Soberanía ↔ integración",institutionalism:"Autoridad ↔ pluralismo",rigidity:"Pragmatismo ↔ dogmatismo"})[key]} <b>{ideology[key]}</b></span><input type="range" min="0" max="100" value={ideology[key]} onChange={(event)=>setIdeology({...ideology,[key]:Number(event.target.value)})}/></label>)}</>}
          {wizardStep===5&&<><h3>Elige 2 o 3 rasgos</h3><p className="wizard-help">Cada rasgo cambia tus fortalezas iniciales y cómo te leen los demás.</p><div className="trait-grid">{traitOptions.map((trait)=><label key={trait.id} className="trait-option"><input type="checkbox" checked={traits.includes(trait.id)} onChange={(event)=>setTraits(event.target.checked?[...traits,trait.id]:traits.filter((id)=>id!==trait.id))} disabled={!traits.includes(trait.id)&&traits.length>=3}/><span>{trait.label}</span></label>)}</div><small>Elegidos: {traits.length} · selecciona entre dos y tres.</small></>}
          {wizardStep===6&&<><h3>Reparte tus atributos</h3><p className="wizard-help">Pool fijo: 70 puntos. La edad mínima para {officeId} es {country.candidateEligibility.find((candidate)=>candidate.officeId===officeId)?.minimumAge ?? 18} años.</p><label>Edad<input type="number" min={country.candidateEligibility.find((candidate)=>candidate.officeId===officeId)?.minimumAge ?? 18} max="100" value={age} onChange={(event)=>setAge(Number(event.target.value))}/></label><label>Partido ficticio<select value={partyId} onChange={(event) => setPartyId(event.target.value)}><option value="">Generar al iniciar</option>{previewParties.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.name}</option>)}</select></label><div className="attribute-list">{(Object.keys(attributes) as AttributeId[]).map((key)=><label className="attribute-row" key={key}><span>{attributeLabels[key]}</span><input type="range" min="1" max="20" value={attributes[key]} onChange={(event)=>adjustAttribute(key,Number(event.target.value))}/><b>{attributes[key]}</b></label>)}</div><div className="character-summary"><strong>{name || "Tu personaje"}</strong><span>{origins.find((item)=>item.id===originId)?.label} · {professions.find((item)=>item.id===professionId)?.label} · {educations.find((item)=>item.id===educationId)?.label}</span></div></>}
          <div className="wizard-actions">{wizardStep>1&&<button type="button" className="secondary-button" onClick={()=>setWizardStep(wizardStep-1)}>Atrás</button>}<button className="primary-button" type="submit" disabled={wizardStep===5&&(traits.length<2||traits.length>3)}>{wizardStep===6?"Empezar campaña":"Siguiente paso"} <span>{wizardStep===6?"↗":"→"}</span></button></div><small>Escenario reproducible · semilla {seed.slice(0, 8)}</small>
        </form></section> : <>
        <nav className="tabbar">{(["career", "inbox", "people", "press", "economy", "world", "country", "help"] as const).map((item) => <button key={item} className={tab === item ? "selected" : ""} onClick={() => setTab(item)}>{({career:"Resumen",inbox:"Bandeja",people:"Congreso",press:"Prensa",economy:"Economía",world:"Mundo",country:"País",help:"Ayuda"})[item]}</button>)}</nav>
        {tab === "help" && <Suspense fallback={<p role="status">Cargando ayuda…</p>}><HelpView/></Suspense>}
        {tab === "world" && <Suspense fallback={<p role="status">Cargando mundo…</p>}><WorldView state={state} country={country} update={setState}/></Suspense>}
        {tab === "career" && <div className="content-grid"><section className="feature-card"><div className="card-head"><div><span className="eyebrow">{stageLabel(state)}</span><h2>{state.stage === "campaign" ? `Semana ${state.campaign.week} de 4` : state.stage === "legislature" ? `Sesión ${state.legislature?.turn ?? 0} de ${state.legislature?.totalTurns ?? 0}` : state.stage === "executive" ? `Trimestre ${state.government?.termTurn ?? 0} de ${state.government?.totalTermTurns ?? 0}` : state.stage === "election-result" ? "Resultado electoral" : "Resumen de carrera"}</h2></div><span className="seat-icon">{state.stage === "legislature" ? "§" : "◎"}</span></div>
          {state.stage === "campaign" ? <><div className="metric-row"><div><span>{(state.campaign.officeId === country.partyLeadership.officeId || state.campaign.officeId === country.ministerialAppointment.officeId) ? "Impacto de campaña" : "Preferencia"}</span><strong>{state.campaign.playerPreferencePercent.toFixed(1)}%</strong></div><div><span>Acciones esta semana</span><strong>{state.campaign.actionsRemaining}/2</strong></div><div><span>Fondos</span><strong>{state.player.resources.campaignFunds.toFixed(0)}k</strong></div></div><div className="progress-track"><i style={{width:`${Math.min(100,state.campaign.playerPreferencePercent*4)}%`}}/></div><h3>Elige una acción</h3><div className="action-grid">{actions.filter((action)=>(state.campaign.officeId !== country.partyLeadership.officeId && state.campaign.officeId !== country.ministerialAppointment.officeId) || action.id !== "make-promise").map((action) => <button key={action.id} disabled={!state.campaign.actionsRemaining} className="action-card" onClick={() => run(() => performCampaignAction(state, action.id))}><strong>{campaignActionCopy(action.id,state.campaign.officeId,country).title}</strong><span>{campaignActionCopy(action.id,state.campaign.officeId,country).hint}</span><b>↗</b></button>)}</div>{state.campaign.districtId === "national" && state.campaign.officeId !== country.ministerialAppointment.officeId && <section className="proposal"><span className="eyebrow">CAMPAÑA NACIONAL</span><h3>Agenda, encuestas y debate</h3><p>Agenda actual: {state.world.socialBlocks.find((block)=>block.id===state.campaign.nationalAgenda)?.name ?? "sin definir"}. Preferencia estimada: {state.campaign.playerPreferencePercent.toFixed(1)}%.</p><div className="action-grid">{state.world.socialBlocks.slice(0,4).map((block)=><button key={block.id} className="secondary-button" disabled={!state.campaign.actionsRemaining || state.player.resources.campaignFunds<0} onClick={()=>run(()=>performCampaignAction(state,"set-national-agenda",block.id))}>Fijar agenda: {block.name}</button>)}<button className="secondary-button" disabled={!state.campaign.actionsRemaining || state.player.resources.campaignFunds<2} onClick={()=>run(()=>performCampaignAction(state,"publish-poll"))}>Publicar encuesta · 2k</button><button className="secondary-button" disabled={!state.campaign.actionsRemaining || state.player.resources.campaignFunds<4} onClick={()=>run(()=>performCampaignAction(state,"national-debate"))}>Participar en debate · 4k</button></div>{state.campaign.pollHistory.slice(-2).map((poll,index)=><p key={`poll-${index}`}>Encuesta semana {poll.week}: {poll.explanation}</p>)}{state.campaign.debateHistory.slice(-2).map((debate,index)=><p key={`debate-${index}`}>Debate semana {debate.week}: {debate.explanation}</p>)}</section>}<div className="button-row"><button className="secondary-button" onClick={() => run(() => nominate(state))}>{state.campaign.officeId === country.ministerialAppointment.officeId ? state.campaign.nominated ? "Candidatura confirmada ✓" : "Confirmar candidatura" : state.campaign.officeId === country.partyLeadership.officeId ? state.campaign.nominated ? "Nominación confirmada ✓" : "Confirmar candidatura" : state.campaign.nominated ? "Nominación confirmada ✓" : "Confirmar nominación"}</button><button className="primary-button" onClick={() => run(() => advanceCareer(state, country))}>Siguiente semana <span>→</span></button></div></> : state.stage === "election-result" ? <><div className="result-banner"><strong>{state.campaign.officeId === country.ministerialAppointment.officeId ? state.electionOutcome?.elected ? "NOMBRAMIENTO MINISTERIAL OBTENIDO" : "NOMBRAMIENTO MINISTERIAL RECHAZADO" : state.campaign.officeId === country.partyLeadership.officeId ? state.electionOutcome?.elected ? "LIDERAZGO PARTIDARIO GANADO" : "LIDERAZGO PARTIDARIO NO OBTENIDO" : state.electionOutcome?.elected ? state.campaign.officeId === country.politicalSystem.executive.officeId ? "CARGO EJECUTIVO GANADO" : "ESCAÑO GANADO" : state.campaign.officeId === country.politicalSystem.executive.officeId ? "SIN CARGO EJECUTIVO" : "SIN ESCAÑO"}</strong><p>{state.electionOutcome?.explanation}</p></div><button className="primary-button wide" onClick={() => run(() => advanceCareer(state, country))}>{state.electionOutcome?.elected ? state.campaign.officeId === country.ministerialAppointment.officeId ? "Iniciar ministerio" : "Iniciar mandato" : "Ver cierre de carrera"} <span>→</span></button></> : state.stage === "legislature" ? <><div className="proposal"><span className="eyebrow">PROPUESTA EN DEBATE</span><h3>{state.legislature?.currentProposal?.title ?? "Votación cerrada"}</h3><p>{state.legislature?.currentProposal?.description ?? "Avanza al siguiente turno para continuar."}</p></div><div className="metric-row"><div><span>Legisladores</span><strong>{legislatorCount}</strong></div><div><span>Acciones</span><strong>{state.legislature?.actionsRemaining}</strong></div><div><span>Votaciones</span><strong>{state.legislature?.voteHistory.length}</strong></div></div>{country.politicalSystem.executive.selection === "legislative-investiture" && <section className="proposal"><span className="eyebrow">FORMACIÓN DE GOBIERNO</span><h3>{state.government?.status === "active" ? "Gobierno en funciones" : "Investidura parlamentaria"}</h3>{!state.government || state.government.status === "ended" || state.government.status === "removed" ? <button className="secondary-button" onClick={() => run(() => startGovernmentInvestiture(state,country))}>Presentar candidatura a la investidura</button> : state.government.status === "awaiting-investiture" ? <><p>Ronda {state.government.round === "first" ? "inicial: mayoría absoluta" : "posterior: mayoría simple"}. Partidos de apoyo: {state.government.supportPartyIds.length}. Capital político: {state.player.resources.politicalCapital}.</p><div className="button-row">{state.world.parties.filter((candidate)=>!state.government?.supportPartyIds.includes(candidate.id)).slice(0,3).map((candidate)=><button className="secondary-button" key={candidate.id} disabled={state.player.resources.politicalCapital<5} onClick={()=>run(()=>negotiateGovernmentSupport(state,candidate.id,country))}>Negociar con {candidate.name}</button>)}<button className="primary-button" onClick={()=>run(()=>resolveGovernmentInvestiture(state,country))}>Votar investidura</button></div></> : <><p>Apoyo afirmativo en la investidura: {state.government.lastInvestitureYes ?? 0}. Gabinete ficticio de {state.government.cabinet.length} ministros.</p><ul>{state.government.cabinet.map((minister)=><li key={minister.officeId}>{minister.title}: {state.world.legislators.find((member)=>member.id===minister.legislatorId)?.name}</li>)}</ul></>}</section>}{state.government?.status === "active" && <section className="proposal"><span className="eyebrow">PROYECTOS DE GOBIERNO</span><p>Presenta una iniciativa y consulta el voto nominal del Gobierno.</p><div className="button-row"><button className="secondary-button" disabled={state.player.resources.politicalCapital<3 || !state.legislature?.actionsRemaining} onClick={()=>run(()=>submitGovernmentProject(state,"employment"))}>Empleo · 3 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3 || !state.legislature?.actionsRemaining} onClick={()=>run(()=>submitGovernmentProject(state,"services"))}>Servicios · 3 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3 || !state.legislature?.actionsRemaining} onClick={()=>run(()=>submitGovernmentProject(state,"investment"))}>Inversión · 3 capital</button></div>{[...(state.government.policyVotes ?? [])].slice(-2).reverse().map((vote)=><p key={vote.id}>{vote.title}: {vote.passed ? "aprobado" : "rechazado"} · {vote.explanation}</p>)}</section>}<div className="button-row"><button className="secondary-button" disabled={!state.legislature?.currentProposal || !state.legislature.actionsRemaining} onClick={() => run(() => castVote(state,"no"))}>Votar en contra</button><button className="primary-button" disabled={!state.legislature?.currentProposal || !state.legislature.actionsRemaining} onClick={() => run(() => castVote(state,"yes"))}>Votar a favor <span>→</span></button></div><button className="text-button" onClick={() => run(() => advanceCareer(state,country))}>Cerrar sesión y avanzar trimestre →</button></> : state.stage === "executive" ? <><div className="result-banner"><strong>MANDATO EN CURSO</strong><p>Tu aprobación es {state.world.approvalPercent.toFixed(1)}%; el gabinete está compuesto por personajes generados.</p></div><h3>Gabinete</h3><ul>{state.government?.cabinet.map((minister)=><li key={minister.officeId}>{minister.title}: {state.world.legislators.find((member)=>member.id===minister.legislatorId)?.name} · lealtad {minister.loyalty}</li>)}</ul><section className="proposal"><span className="eyebrow">INICIATIVAS DEL EJECUTIVO</span><h3>Decretos y proyectos</h3><p>Decretos: acciones ejecutivas con efecto moderado. Proyectos: votación nominal de la cámara; la mayoría de más de 50% es una abstracción del prototipo.</p><div className="action-grid"><button className="secondary-button" disabled={state.player.resources.politicalCapital<4} onClick={()=>run(()=>issueExecutiveDecree(state,"services"))}>Decreto de servicios · 4 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<4} onClick={()=>run(()=>issueExecutiveDecree(state,"investment"))}>Decreto de inversión · 4 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3} onClick={()=>run(()=>submitGovernmentProject(state,"employment"))}>Proyecto de empleo · 3 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3} onClick={()=>run(()=>submitGovernmentProject(state,"services"))}>Proyecto de servicios · 3 capital</button><button className="secondary-button" disabled={state.player.resources.politicalCapital<3} onClick={()=>run(()=>submitGovernmentProject(state,"investment"))}>Plan de inversión · 3 capital</button></div>{[...(state.government?.policyVotes ?? [])].slice(-3).reverse().map((vote)=><article key={vote.id}><strong>{vote.title} · {vote.passed ? "aprobado" : "rechazado"}</strong><p>{vote.explanation}</p><details><summary>Ver papeletas</summary>{vote.votes.map((ballot)=><p key={ballot.legislatorId}>{state.world.legislators.find((member)=>member.id===ballot.legislatorId)?.name ?? ballot.legislatorId}: {ballot.choice} — {ballot.reasons.join(" ")}</p>)}</details></article>)}</section><button className="primary-button wide" onClick={() => run(() => advanceCareer(state,country))}>Avanzar trimestre <span>→</span></button></>  : state.stage === "minister" ? <><div className="result-banner"><strong>MINISTERIO EN FUNCIONES · {country.ministerialAppointment.portfolios.find((portfolio)=>portfolio.id===state.ministry?.portfolioId)?.title.toUpperCase()}</strong><p>Nombramiento de {state.world.legislators.find((member)=>member.id===state.ministry?.authorityId)?.name ?? "un ejecutivo NPC"} · respaldo {state.ministry?.supportPercent.toFixed(1)}% · el cargo dura hasta el término configurado o hasta que caiga el respaldo ejecutivo.</p></div><div className="metric-row"><div><span>Trimestre</span><strong>{state.ministry?.termTurn}/{state.ministry?.totalTermTurns}</strong></div><div><span>Apoyo ejecutivo</span><strong>{state.ministry?.supportPercent.toFixed(1)}%</strong></div><div><span>Acciones disponibles</span><strong>{state.ministry?.actionsRemaining}/2</strong></div></div><h3>Decisiones ministeriales</h3><div className="action-grid"><button className="action-card" disabled={!state.ministry?.actionsRemaining} onClick={()=>run(()=>performMinistryAction(state,country,"deliver-results"))}><strong>Entregar resultados</strong><span>No cuesta capital. Mejora las variables prioritarias de la cartera.</span></button><button className="action-card" disabled={!state.ministry?.actionsRemaining || state.player.resources.politicalCapital<4} onClick={()=>run(()=>performMinistryAction(state,country,"negotiate-resources"))}><strong>Negociar recursos</strong><span>Cuesta 4 de capital y fortalece tu relación con el ejecutivo.</span></button><button className="action-card" disabled={!state.ministry?.actionsRemaining || state.player.resources.politicalCapital<3} onClick={()=>run(()=>performMinistryAction(state,country,"manage-crisis"))}><strong>Gestionar una crisis</strong><span>Cuesta 3 de capital y protege la cartera ante una presión inmediata.</span></button></div><h3>Registro ministerial</h3><ul>{state.ministry?.actionsTaken.slice(-4).map((entry,index)=><li key={`${entry.turn}-${index}`}>Trimestre {entry.turn}: {entry.explanation}</li>)}</ul><button className="primary-button wide" onClick={()=>run(()=>advanceCareer(state,country))}>Avanzar trimestre <span>→</span></button></> : state.stage === "party-leadership" ? <><div className="result-banner"><strong>{state.partyLeadership?.role === "opposition" ? "LIDERAZGO DE OPOSICIÓN EN CURSO" : "LIDERAZGO PARTIDARIO EN CURSO"}</strong><p>{party?.name ?? "Tu partido ficticio"} · {state.partyLeadership?.role === "opposition" ? "tu bancada ejerce control político desde la oposición" : "tu bancada forma parte del bloque de gobierno"} · respaldo {state.partyLeadership?.supportPercent.toFixed(1)}%.</p></div><div className="metric-row"><div><span>Trimestre</span><strong>{state.partyLeadership?.termTurn}/{state.partyLeadership?.totalTermTurns}</strong></div><div><span>Acciones disponibles</span><strong>{state.partyLeadership?.actionsRemaining}/2</strong></div><div><span>Capital político</span><strong>{state.player.resources.politicalCapital.toFixed(0)}</strong></div></div><h3>Decisiones de liderazgo</h3><div className="action-grid"><button className="action-card" disabled={!state.partyLeadership?.actionsRemaining || state.player.resources.politicalCapital<5} onClick={()=>run(()=>performPartyLeadershipAction(state,"unify-factions"))}><strong>Unificar facciones</strong><span>Cuesta 5 de capital. Mejora lealtad y respaldo interno.</span></button><button className="action-card" disabled={!state.partyLeadership?.actionsRemaining || state.player.resources.politicalCapital<3} onClick={()=>run(()=>performPartyLeadershipAction(state,"renew-platform"))}><strong>Renovar la plataforma</strong><span>Cuesta 3 de capital. Sube ligeramente el respaldo público y la cohesión.</span></button><button className="action-card" disabled={!state.partyLeadership?.actionsRemaining || state.player.resources.politicalCapital<4} onClick={()=>run(()=>performPartyLeadershipAction(state,"enforce-discipline"))}><strong>Imponer disciplina</strong><span>Cuesta 4 de capital. Refuerza la disciplina con costos de lealtad y apoyo público.</span></button></div><h3>Decisiones anteriores</h3><ul>{state.partyLeadership?.actionsTaken.slice(-4).map((entry,index)=><li key={`${entry.turn}-${index}`}>Trimestre {entry.turn}: {entry.explanation}</li>)}</ul><button className="primary-button wide" onClick={()=>run(()=>advanceCareer(state,country))}>Avanzar trimestre <span>→</span></button></> : state.stage === "term-summary" ? <><div className="result-banner"><strong>MANDATO CERRADO</strong><p>El historial político, los votos, las promesas y las decisiones de {state.player.name} quedan listos para valorar.</p></div><h3>Continuar la carrera</h3><p>Elige otro cargo permitido por las instituciones del país o cierra tu trayectoria.</p><div className="button-row career-option-grid">{country.ministerialAppointment.portfolios.filter((portfolio)=>canStartMinisterialAppointment(state,country,portfolio.id)).map((portfolio)=><button className="secondary-button" key={portfolio.id} onClick={()=>run(()=>startMinisterialAppointment(state,country,portfolio.id))}>Postular a ministro de {portfolio.title}</button>)}{canStartPartyLeadershipElection(state,country) && <button className="secondary-button" onClick={()=>run(()=>startPartyLeadershipElection(state,country))}>Competir por {party?.name && state.government?.supportPartyIds.includes(state.playerPartyId) ? country.partyLeadership.title.toLowerCase() : "el liderazgo de oposición"}</button>}{country.candidateEligibility.filter((candidate)=>canStartNextCareerCampaign(state,country,candidate.officeId)).map((candidate)=><button className="secondary-button" key={candidate.officeId} onClick={()=>run(()=>startNextCareerCampaign(state,country,candidate.officeId))}>Postular a {candidate.officeId}</button>)}</div><section className="proposal"><span className="eyebrow">AFILIACIÓN Y ORGANIZACIÓN</span><h3>{party?.name ?? "Tu partido"}</h3><p>Cambiar de partido cuesta 4 puntos de capital y deja resentimiento en la bancada anterior. Fundar una organización cuesta 8 puntos de capital y 15 mil de fondos.</p><label>Afiliarte a otro partido<select aria-label="Afiliarte a otro partido" value={partySwitchTarget} onChange={(event)=>setPartySwitchTarget(event.target.value)}><option value="">Elegir partido</option>{state.world.parties.filter((candidate)=>candidate.id!==state.playerPartyId).map((candidate)=><option key={candidate.id} value={candidate.id}>{candidate.name}</option>)}</select></label><button className="secondary-button" disabled={!partySwitchTarget||state.player.resources.politicalCapital<4} onClick={()=>run(()=>changePartyAffiliation(state,partySwitchTarget))}>Cambiar de partido</button><label>Nombre del nuevo partido<input aria-label="Nombre del nuevo partido" minLength={3} maxLength={48} value={foundPartyName} onChange={(event)=>setFoundPartyName(event.target.value)} placeholder="Una organización propia"/></label><button className="secondary-button" disabled={foundPartyName.trim().length<3||state.player.resources.politicalCapital<8||state.player.resources.campaignFunds<15} onClick={()=>run(()=>foundParty(state,foundPartyName))}>Fundar partido</button></section><button className="primary-button wide" onClick={() => run(() => retireCareer(state))}>Retirarme y generar mi legado</button></> : <><div className="result-banner"><strong>LEGADO · {state.legacy?.archetype.toUpperCase()}</strong><p>{state.legacy?.summary}</p></div><h3>Momentos que definieron la carrera</h3><ul>{state.legacy?.milestones.map((milestone,index)=><li key={index}>{milestone}</li>)}</ul><div className="metric-row"><div><span>Revisión a 5 años</span><strong>{state.legacy?.reevaluationAt5}</strong></div><div><span>Revisión a 15 años</span><strong>{state.legacy?.reevaluationAt15}</strong></div><div><span>Revisión a 30 años</span><strong>{state.legacy?.reevaluationAt30 ?? "—"}</strong></div><div><span>Estado</span><strong>{state.lifeStatus === "deceased" ? "Fallecido" : "Retirado"}</strong></div></div>{state.lifeStatus === "retired" && <><button onClick={()=>void navigator.clipboard.writeText(state.legacy?.shareText ?? "")}>Copiar tarjeta</button>{state.returnCall.status === "offered" ? <><p>{party?.name ?? "Tu partido ficticio"} te ofrece volver. Aceptar agrega tres puntos de respaldo inicial.</p><button className="primary-button" onClick={() => run(() => returnFromRetirement(state,"deputy",country,"party-call"))}>Aceptar el llamado</button><button className="secondary-button" onClick={() => run(() => declineReturnCall(state))}>Rechazar y seguir retirado</button><label>Nombre del nuevo partido<input aria-label="Nombre del partido para volver" minLength={3} maxLength={48} value={foundPartyName} onChange={(event)=>setFoundPartyName(event.target.value)} placeholder="Una organización propia"/></label><button className="secondary-button" disabled={foundPartyName.trim().length<3||state.player.resources.politicalCapital<8||state.player.resources.campaignFunds<15} onClick={()=>run(()=>foundParty(state,foundPartyName,country,"deputy"))}>Fundar partido y volver como agente libre</button></> : <><button className="primary-button wide" onClick={() => run(() => returnFromRetirement(state,"deputy",country,"agent-free"))}>Volver como agente libre</button><label>Nombre del nuevo partido<input aria-label="Nombre del partido para volver" minLength={3} maxLength={48} value={foundPartyName} onChange={(event)=>setFoundPartyName(event.target.value)} placeholder="Una organización propia"/></label><button className="secondary-button" disabled={foundPartyName.trim().length<3||state.player.resources.politicalCapital<8||state.player.resources.campaignFunds<15} onClick={()=>run(()=>foundParty(state,foundPartyName,country,"deputy"))}>Fundar partido y volver como agente libre</button></>}<h3>Hacedor de reyes</h3><p>Apoya a una figura ficticia para aumentar su influencia.</p><div className="button-row">{state.world.legislators.slice(0,3).map((successor)=><button className="secondary-button" key={successor.id} onClick={()=>run(()=>backSuccessor(state,successor.id))}>Respaldar a {successor.name}</button>)}</div></>}</>}
        </section>{state.government?.status === "active" && <section className="side-card"><span className="eyebrow">ESTABILIDAD DEL GOBIERNO</span><h3>Riesgo {state.realism === "relentless" ? state.government.fallRiskPercent >= 55 ? "alto" : state.government.fallRiskPercent >= 30 ? "medio" : "bajo" : `${state.government.fallRiskPercent}%`}</h3>{state.government.warningSignals.length ? <ul>{state.government.warningSignals.map((signal)=><li key={signal}>{signal}</li>)}</ul> : <p>Sin señales de alerta. El apoyo y la aprobación sostienen el mandato.</p>}<h3>Reorganizar gabinete</h3>{state.government.cabinet.map((minister)=><details key={minister.officeId}><summary>{minister.title}</summary>{state.world.legislators.filter((member)=>member.chamberId===state.government?.chamberId&&member.id!==minister.legislatorId).slice(0,3).map((member)=><button className="text-button" key={member.id} onClick={()=>run(()=>appointMinister(state,minister.officeId,member.id))}>Nombrar a {member.name} · {member.loyalty} lealtad</button>)}</details>)}{state.government.challenge ? <><p>Procedimiento: {state.government.challenge.type} · fase {state.government.challenge.phase} · día {state.government.challenge.daysElapsed}.{state.government.challenge.successorId ? ` Sucesor propuesto: ${state.world.legislators.find((member)=>member.id===state.government?.challenge?.successorId)?.name ?? "NPC"}.` : ""}</p><div className="button-row">{state.government.challenge.phase === "defense" && <button className="secondary-button" onClick={()=>run(()=>defendGovernment(state))}>Defender al Gobierno</button>}<button className="secondary-button" onClick={()=>run(()=>advanceChallengeDays(state,country,state.government?.challenge?.phase === "admission" ? 3 : 5))}>Avanzar días del procedimiento</button>{state.government.challenge.phase === "defense" && <button className="primary-button" onClick={()=>run(()=>resolveGovernmentChallenge(state,country))}>Resolver votación</button>}</div></> : <button className="secondary-button" onClick={()=>run(()=>submitGovernmentChallenge(state,country))}>Iniciar procedimiento de control</button>}</section>}{(state.government?.status === "active" || state.stage === "legislature") && <section className="side-card"><span className="eyebrow">PRESUPUESTO ANUAL</span><h3>Ejercicio {state.budget.fiscalYear}</h3><p>Ingresos índice {state.budget.revenueIndex.toFixed(1)} · gasto {state.budget.spendingIndex.toFixed(1)} · deuda {state.budget.debtIndex.toFixed(1)}</p><ul><li>Servicios públicos: {state.budget.servicesSharePercent}%</li><li>Inversión: {state.budget.investmentSharePercent}%</li><li>Transferencias: {state.budget.transfersSharePercent}%</li><li>Seguridad: {state.budget.securitySharePercent}%</li></ul><p>{state.budget.lastProposalQuarterIndex > state.budget.lastApprovedQuarterIndex ? "Hay una propuesta anual pendiente en la bandeja." : state.budget.lastDecisionId ? `Última decisión: ${state.budget.lastDecisionId}.` : "Aún no se ha aprobado una decisión anual."}</p>{latestBudgetVote && <details><summary>Actas de votación presupuestaria ({state.budget.voteHistory.length}) · última {latestBudgetVote.passed ? "aprobada" : "rechazada"}</summary>{[...state.budget.voteHistory].reverse().map((vote,index)=><details key={`${vote.turn}-${index}`}><summary>Trimestre {vote.turn} · {vote.passed ? "aprobada" : "rechazada"} · {vote.yes} a favor, {vote.no} en contra</summary><div className="vote-reasons">{vote.votes.map((ballot)=>{const voter=state.world.legislators.find((member)=>member.id===ballot.legislatorId);return <p key={ballot.legislatorId}><strong>{voter?.name ?? ballot.legislatorId} · {ballot.choice}</strong> — {ballot.reasons.join(" ")}</p>})}</div></details>)}</details>}</section>}<aside className="side-stack"><section className="side-card"><span className="eyebrow">DIARIO DE CAMPAÑA</span><h3>Lo que ha pasado</h3><ol className="log-list">{[...state.log].reverse().slice(0,5).map((entry,index)=><li key={`${entry.turn}-${index}`}><span className="log-dot"/><div><strong>{entry.text}</strong><p>{entry.explanation}</p></div></li>)}</ol></section><section className="side-card compact"><span className="eyebrow">TU ORGANIZACIÓN</span><h3>{party?.name ?? "Partido de la partida"}</h3><p>Facción ficticia · {state.ministry ? `cartera de ${country.ministerialAppointment.portfolios.find((portfolio)=>portfolio.id===state.ministry?.portfolioId)?.title}` : `lista del distrito de ${country.electoralDistricts.find((district)=>district.id===state.campaign.districtId)?.name ?? "escenario nacional"}`}</p></section></aside></div>}
        {tab === "inbox" && <section className="side-card full-card"><span className="eyebrow">BANDEJA DE CARRERA</span><h2>Decisiones y actividad</h2>{state.inbox.filter((item)=>!item.resolved).length ? <div className="inbox-grid">{[...state.inbox].reverse().filter((item)=>!item.resolved).map((item)=><article className="inbox-item" key={item.id}><span className="eyebrow">{item.category} · PRIORIDAD {item.priority}</span><h3>{item.title}</h3><p>{item.body}</p><small>{item.explanation}</small><div className="inbox-options">{item.options.map((option)=><button key={option.id} className={option.actionType === "advance" ? "secondary-button" : "primary-button"} title={option.consequenceHint} onClick={()=>run(()=>resolveInboxOption(state,item.id,option.id))}>{option.label}</button>)}</div></article>)}</div> : <p>Tu bandeja está al día.</p>}<h3>Diario</h3><ol className="log-list">{[...state.log].reverse().map((entry,index)=><li key={`${entry.turn}-${index}`}><span className="log-dot"/><div><strong>{entry.text}</strong><p>{entry.explanation}</p></div></li>)}</ol></section>}
        {tab === "people" && <section className="side-card full-card"><span className="eyebrow">LEGISLATURA GENERADA</span><h2>{state.world.legislators.length} representantes ficticios</h2><p>El escenario conserva estructura, escaños y circunscripciones del país. Los partidos, legisladores y sus votos se generan en esta partida.</p><div className="people-grid">{state.world.parties.map((item)=><div key={item.id}><strong>{item.name}</strong><span>{item.supportPercent}% de apoyo · disciplina {item.discipline}</span></div>)}</div><div className="member-controls"><input value={memberQuery} onChange={(event)=>setMemberQuery(event.target.value)} placeholder="Filtrar por nombre, partido o código" aria-label="Filtrar legisladores"/><span>{visibleMembers.length} visibles</span></div><div className="legislator-list">{visibleMembers.map((member)=>{const memberParty=state.world.parties.find((item)=>item.id===member.partyId);const faction=state.world.factions.find((item)=>item.id===member.factionId);const relation=state.relationships.find((item)=>item.legislatorId===member.id);return <article key={member.id} className="legislator-card"><div><strong>{member.name}</strong><span>{memberParty?.name} · {faction?.name}</span><small>{member.districtId} · lealtad {Math.round(member.loyalty)} · integridad {member.integrity}/20 · confianza {Math.round(relation?.trust??0)}</small></div>{state.stage==="legislature"&&member.id!==state.legislature?.playerLegislatorId&&<div className="member-actions"><button disabled={!state.legislature?.actionsRemaining} onClick={()=>run(()=>negotiateWithLegislator(state,member.id))}>Negociar</button><button disabled={!state.legislature?.actionsRemaining} onClick={()=>run(()=>applyBetrayalMemory(state,member.id,"Rompiste el acuerdo de apoyo al debate."))}>Romper acuerdo</button></div>}</article>})}</div>{state.legislature?.voteHistory.map((record)=><article className="vote-report" key={record.proposal.id}><h3>{record.proposal.title} · {record.passed ? "Aprobada" : "Rechazada"}</h3><p>{record.explanation}</p><details><summary>Ver razones de cada legislador</summary><div className="vote-reasons">{record.votes.map((vote)=>{const voter=state.world.legislators.find((member)=>member.id===vote.legislatorId);return <p key={vote.legislatorId}><strong>{voter?.name ?? vote.legislatorId} · {vote.choice}</strong> — {vote.reasons.join(" ")}</p>})}</div></details></article>)}</section>}
        {tab === "press" && <section className="side-card full-card"><span className="eyebrow">PRENSA · {pressItems.length} ACTUALIZACIONES</span><h2>Lo que mueve el debate</h2><p>Cada titular se genera desde un evento, decisión o voto ocurrido en esta partida.</p><div className="press-feed">{pressItems.length?pressItems.map((item)=><article key={item.id}><span className="eyebrow">TURNO {item.turn} · {item.source}</span><h3>{item.headline}</h3><p>{item.explanation}</p></article>):<p>La prensa espera el primer evento de campaña.</p>}</div></section>}
        {tab === "economy" && <section className="side-card full-card"><span className="eyebrow">ECONOMÍA · ESCENARIO {state?.world.economy.snapshotYear ?? ""}</span><h2>El país, sus sectores y sus tensiones</h2>{state && <><p>Modelo determinista con parámetros versionados. Son aproximaciones de simulación, no pronósticos. Confianza: instituciones {state.world.publicAgenda.institutionalTrust.toFixed(0)} · partido {state.world.publicAgenda.partyTrust.toFixed(0)} · electorado {state.world.publicAgenda.electorateTrust.toFixed(0)} · polarización {state.world.publicAgenda.polarization.toFixed(0)}.</p><div className="country-facts">{Object.entries(state.world.economy.indicators).map(([id,value])=><div key={id}><span>{indicatorLabels[id] ?? id}</span><strong>{value.toLocaleString("es-PE",{maximumFractionDigits:1})}{id.endsWith("Percent") || id.includes("PercentGdp") || id === "gdpGrowthPercent" ? "%" : ""}</strong><details><summary>¿Por qué cambió?</summary><ul>{(state.world.economy.causesByIndicator[id] ?? ["El indicador forma parte del escenario inicial.","Las variables económicas interactúan por trimestre.","Las decisiones y los shocks modifican su trayectoria."]).slice(0,3).map((cause,index)=><li key={index}>{cause}</li>)}</ul></details></div>)}</div><h3>Actividad por sector</h3><div className="people-grid">{state.world.economy.sectors.map((sector)=><article key={sector.id}><strong>{sector.name}</strong><span>{sector.gdpSharePercent}% del PIB · crecimiento {sector.annualGrowthPercent.toFixed(1)}% · índice {sector.outputIndex.toFixed(1)}</span></article>)}</div><h3>Fiscalidad y economía</h3><div className="country-facts"><div><span>Gasto público / PIB</span><strong>{state.world.economy.publicSpendingPercentGdp.toFixed(1)}%</strong></div><div><span>Impuestos / PIB</span><strong>{state.world.economy.taxBurdenPercentGdp.toFixed(1)}%</strong></div><div><span>Apertura comercial</span><strong>{state.world.economy.tradeOpennessPercent.toFixed(1)}%</strong></div><div><span>Propiedad pública</span><strong>{state.world.economy.publicOwnershipPercent.toFixed(1)}%</strong></div></div><h3>Proyección aproximada a un año</h3><p>Crecimiento: {(state.world.economy.indicators.gdpGrowthPercent-1.5).toFixed(1)}% a {(state.world.economy.indicators.gdpGrowthPercent+1.5).toFixed(1)}%; inflación: {Math.max(-5,state.world.economy.indicators.inflationPercent-1.2).toFixed(1)}% a {(state.world.economy.indicators.inflationPercent+1.2).toFixed(1)}%. El rango expresa incertidumbre y shocks.</p><h3>Crisis y respuestas</h3>{state.world.economy.crises.length ? state.world.economy.crises.map(crisis=><article className="vote-report" key={crisis.type}><strong>{({inflation:"Inflación",currency:"Balanza de pagos",debt:"Deuda",banking:"Banca","demand-recession":"Recesión de demanda"} as const)[crisis.type]} · gravedad {crisis.severity.toFixed(0)}</strong><p>{crisis.explanation}</p><ul>{economicModelParameters.crisisResponses[crisis.type].map(choice=><li key={choice.policyId}><strong>{choice.title}:</strong> {choice.explanation}</li>)}</ul></article>) : <p>No hay crisis activas.</p>}<h3>Agenda y sociedad</h3><div className="people-grid">{state.world.publicAgenda.issues.map(issue=><article key={issue.id}><strong>{issue.id.replaceAll("-"," ")}</strong><span>Atención {issue.salience.toFixed(0)} · {state.world.parties.find(item=>item.id===issue.ownerPartyId)?.name ?? "sin propietario"}</span></article>)}</div><div className="people-grid">{state.world.socialBlocks.map(block=><article key={block.id}><strong>{block.name}</strong><span>Ánimo {block.mood.toFixed(0)} · demandas pendientes {block.unmetDemandIndex?.toFixed(0)} · presión {block.pressurePower?.toFixed(0)}</span><small>{block.demands.join(" · ")}</small></article>)}</div>{state.world.publicAgenda.collectiveActions.slice(-5).reverse().map(action=><article className="vote-report" key={action.id}><strong>{action.type.toUpperCase()} · {state.world.socialBlocks.find(block=>block.id===action.blockId)?.name}</strong><p>{action.explanation}</p></article>)}<h3>Palancas de política económica</h3><p>El capital político paga el costo de presentación. La legislación enfrenta votación; el decreto depende de las facultades institucionales y la cohabitación.</p><div className="member-controls"><select value={economicPolicyId} onChange={event=>setEconomicPolicyId(event.target.value as EconomicPolicyId)} aria-label="Política económica">{Object.keys(economicModelParameters.policyEffects).map(id=><option key={id} value={id}>{policyLabels[id as EconomicPolicyId]}</option>)}</select><span>Costo {economicModelParameters.policyEffects[economicPolicyId].politicalCost} · rezago {economicModelParameters.policyEffects[economicPolicyId].lagQuarters} trimestres</span></div><p>Apoyo legislativo estimado: {economicPolicyApprovalPercent(state,economicPolicyId).toFixed(0)}% · ganadores: {economicModelParameters.policyEffects[economicPolicyId].winners.join(", ")} · costos: {economicModelParameters.policyEffects[economicPolicyId].losers.join(", ")}</p>{country.politicalSystem.cohabitation && <p>Autoridad efectiva del Gobierno: {executiveAuthorityPercent(state,country)}% {state.government && state.world.headOfStatePartyId !== null && !state.government.supportPartyIds.includes(state.world.headOfStatePartyId) ? "· cohabitación activa" : "· mayorías alineadas"}.</p>}{state.stage === "executive" && state.government?.status === "active" ? <div className="member-actions"><button onClick={()=>run(()=>enactEconomicPolicy(state,country,economicPolicyId,"legislation"))}>Presentar al Congreso</button><button disabled={!economicPolicyCanBeDecreed(state,country)} onClick={()=>run(()=>enactEconomicPolicy(state,country,economicPolicyId,"decree"))}>Aplicar por decreto</button></div> : <p>Las medidas se habilitan al encabezar un Gobierno activo.</p>}</>}</section>}        {tab === "country" && <section className="side-card full-card"><span className="eyebrow">DATOS E INSTITUCIONES</span><h2>{country.name}</h2><p>Ficha versionada {country.dataVersion}. El juego utiliza parámetros institucionales y económicos fechados; genera la política de cada partida.</p>{country.politicalSystem.legislature.type === "bicameral" && country.politicalSystem.legislature.upperChamber.appointments && <p className="source-note">La cámara alta representa nombramientos o delegaciones institucionales. El motor agrupa sus puestos para la jugabilidad; no simula cada órgano territorial ni su procedimiento de voto.</p>}<div className="country-facts"><div><span>Gobierno</span><strong>{country.politicalSystem.formOfGovernment}</strong></div><div><span>Legislatura</span><strong>{country.politicalSystem.legislature.type}</strong></div><div><span>Distritos</span><strong>{country.electoralDistricts.length}</strong></div><div><span>Exportaciones de bienes</span><strong>US$ {(country.trade.goodsExportsUsd/1e9).toFixed(1)} mil M · {country.trade.dataYear}</strong></div></div><h3>Instituciones del país</h3><ul>{(country.politicalSystem.legislature.type === "bicameral" ? [country.politicalSystem.legislature.lowerChamber,country.politicalSystem.legislature.upperChamber] : [country.politicalSystem.legislature.lowerChamber]).map((chamber)=><li key={chamber.id}>{chamber.name}: {chamber.seats} escaños · {chamber.termYears} años · {chamber.electoralSystem}</li>)}</ul><div className="source-list"><span className="eyebrow">FUENTES VERSIONADAS</span>{country.dataSources.map((source)=><a key={source.url} href={source.url} target="_blank" rel="noreferrer">{source.name} · {source.year} ↗</a>)}</div></section>}
      </>}
      <footer>MANDATO <span>·</span> Ficción política y sátira; personajes y partidos generados <span>·</span> Guardado solo en este dispositivo <span>·</span> Datos {country.dataVersion} · {state?.geopolitics.dataVersion ?? "mundo v1"}<div className="footer-links"><a href="/privacy.html">Privacidad</a><a href="https://github.com/yohandry10/juego/issues" target="_blank" rel="noreferrer">Reportar un error ↗</a></div></footer>
    </section>
  </main>;
}

function stageLabel(state: CareerGameState) { return ({ campaign: "CAMPAÑA", "election-result": "ELECCIÓN", legislature: "LEGISLATURA", executive: "GOBIERNO", "party-leadership": "LIDERAZGO PARTIDARIO", minister: "MINISTERIO", "term-summary": "CIERRE", legacy: "LEGADO" })[state.stage]; }
